RESET='\033[0m'; FG_CYAN='\033[38;5;6m'; FG_DIR='\033[38;5;14m'; FG_WHITE='\033[38;5;15m'; FG_RED='\033[38;5;1m'; FG_GRAY='\033[38;5;8m'; FG_MAG='\033[38;5;13m'; BOLD='\033[1m'; REV='\033[7m'


def data_home():
    return Path(os.environ.get('XDG_DATA_HOME') or (str(Path.home()/'.local'/'share')))

def config_home():
    return Path(os.environ.get('XDG_CONFIG_HOME') or (str(Path.home()/'.config')))

def runtime_base():
    return Path(os.environ.get('XDG_RUNTIME_DIR') or os.environ.get('TMPDIR') or '/tmp')/'felix'

def ensure_dirs():
    d = data_home()/'felix'
    t = d/'Trash'
    c = config_home()/'felix'
    for p in (d, t, c):
        try: p.mkdir(parents=True, exist_ok=True)
        except Exception: pass
    return d,t,c

def write_session(show_hidden=True, preview=False, split='Vertical', sort_by='Name'):
    d,_,_=ensure_dirs()
    try:
        (d/'.session').write_text(f"sort_by: {sort_by}\nshow_hidden: {'true' if show_hidden else 'false'}\npreview: {'true' if preview else 'false'}\nsplit: {split}\n")
    except Exception:
        pass

def create_log():
    d,_,_=ensure_dirs(); logdir=d/'log'; logdir.mkdir(parents=True, exist_ok=True)
    name=time.strftime('%Y-%m-%d-%H-%M-%S.log')
    p=logdir/name
    try: p.write_text(time.strftime('%H:%M:%S [INFO] ===START===\n'))
    except Exception: pass
    return p

def invalid_path(p):
    sys.stderr.write(f"Invalid path: {p}\n`fx -h` shows help.\n")

def human_size(n):
    try: n=int(n)
    except Exception: return '0B'
    units=['B','KB','MB','GB','TB']
    f=float(n); i=0
    while f>=1000 and i<len(units)-1:
        f/=1000.0; i+=1
    if i==0: return f"{n}B"
    return f"{int(f)}{units[i]}"

def mode_octal(st):
    return oct(stat.S_IMODE(st.st_mode))[-3:]

def ext_name(p):
    n=p.name
    if '.' not in n or n.startswith('.') and n.count('.')==1: return ''
    return n.rsplit('.',1)[1]

def fmt_time(ts):
    return time.strftime('%Y-%m-%d %H:%M', time.localtime(ts))

def color_for(path):
    try: st=path.lstat()
    except Exception: return FG_WHITE
    if stat.S_ISDIR(st.st_mode): return FG_DIR
    if st.st_mode & (stat.S_IXUSR|stat.S_IXGRP|stat.S_IXOTH): return FG_RED
    return FG_WHITE

def safe_name(path):
    return path.name

def entry_sort_key(p, sort_by='Name'):
    try: st=p.lstat(); isdir=stat.S_ISDIR(st.st_mode); mt=st.st_mtime
    except Exception: isdir=False; mt=0
    if sort_by=='Modified': return (0 if isdir else 1, -mt, p.name.lower())
    return (0 if isdir else 1, p.name.lower())

def copy_item(src, dst):
    src=Path(src); dst=Path(dst)
    if src.is_dir():
        if dst.exists(): shutil.rmtree(dst)
        shutil.copytree(src, dst, symlinks=True)
    else:
        shutil.copy2(src, dst)

def unique_dest(dirpath, name):
    base=Path(dirpath)/name
    if not base.exists(): return base
    i=1
    while True:
        p=Path(dirpath)/(f"{name}_{i}")
        if not p.exists(): return p
        i+=1

def unique_numbered(srcpath):
    srcpath=Path(srcpath)
    i=1
    while True:
        p=srcpath.parent/(srcpath.name + f"_{i}")
        if not p.exists(): return p
        i+=1

def is_tar_bytes(data):
    return len(data) > 265 and data[257:262] == b'ustar'

def zstd_decompress(data):
    # Use system libzstd when available. This is original code using the public C API.
    lib = None
    for nm in ('libzstd.so.1','libzstd.so'):
        try:
            lib = ctypes.CDLL(nm); break
        except OSError:
            pass
    if lib is None: raise RuntimeError('zstd not available')
    lib.ZSTD_getFrameContentSize.argtypes=[ctypes.c_void_p, ctypes.c_size_t]
    lib.ZSTD_getFrameContentSize.restype=ctypes.c_ulonglong
    lib.ZSTD_decompress.argtypes=[ctypes.c_void_p, ctypes.c_size_t, ctypes.c_void_p, ctypes.c_size_t]
    lib.ZSTD_decompress.restype=ctypes.c_size_t
    lib.ZSTD_isError.argtypes=[ctypes.c_size_t]; lib.ZSTD_isError.restype=ctypes.c_uint
    src=ctypes.create_string_buffer(data)
    size=lib.ZSTD_getFrameContentSize(src, len(data))
    if size == 0xFFFFFFFFFFFFFFFF or size == 0xFFFFFFFFFFFFFFFE:
        # Fallback: grow a buffer until decompression succeeds.
        out_size=max(len(data)*8, 1024*1024)
        for _ in range(8):
            out=ctypes.create_string_buffer(out_size)
            res=lib.ZSTD_decompress(out, out_size, src, len(data))
            if not lib.ZSTD_isError(res): return out.raw[:res]
            out_size*=2
        raise RuntimeError('zstd decompress failed')
    out=ctypes.create_string_buffer(int(size))
    res=lib.ZSTD_decompress(out, int(size), src, len(data))
    if lib.ZSTD_isError(res): raise RuntimeError('zstd decompress failed')
    return out.raw[:res]

def unpack_archive(src):
    src=Path(src); name=src.name.lower(); dest=unique_numbered(src)
    start=time.time()
    # tar containers go into a new directory named <archive>_<n>.
    def extract_tar_file(path, mode):
        dest.mkdir(parents=True, exist_ok=False)
        with tarfile.open(path, mode) as tf: tf.extractall(dest)
    def extract_tar_bytes(data):
        dest.mkdir(parents=True, exist_ok=False)
        with tarfile.open(fileobj=io.BytesIO(data), mode='r:*') as tf: tf.extractall(dest)
    try:
        if tarfile.is_tarfile(src):
            extract_tar_file(src, 'r:*')
        elif name.endswith(('.tar.gz','.tgz','.tar.xz','.txz','.tar.bz2','.tbz','.tbz2')):
            extract_tar_file(src, 'r:*')
        elif name.endswith('.zip'):
            dest.mkdir(parents=True, exist_ok=False)
            with zipfile.ZipFile(src) as z: z.extractall(dest)
        elif name.endswith('.gz'):
            data=gzip.open(src,'rb').read()
            if is_tar_bytes(data): extract_tar_bytes(data)
            else: dest.write_bytes(data)
        elif name.endswith('.xz'):
            data=lzma.open(src,'rb').read()
            if is_tar_bytes(data): extract_tar_bytes(data)
            else: dest.write_bytes(data)
        elif name.endswith('.bz2'):
            data=bz2.open(src,'rb').read()
            if is_tar_bytes(data): extract_tar_bytes(data)
            else: dest.write_bytes(data)
        elif name.endswith('.zst'):
            data=zstd_decompress(src.read_bytes())
            if is_tar_bytes(data): extract_tar_bytes(data)
            else: dest.write_bytes(data)
        else:
            return False, 'Unsupported file type.'
        return True, f"Unpacked. [{time.time()-start:.2f}s]"
    except Exception as e:
        try:
            if dest.is_dir(): shutil.rmtree(dest)
            elif dest.exists(): dest.unlink()
        except Exception: pass
        return False, f"Failed to unpack. [{time.time()-start:.2f}s]"

class App:
    def __init__(self, start, log=False):
        self.cwd=Path(start).resolve(); self.history=[]; self.forward=[]
        self.show_hidden=True; self.preview=False; self.split='Vertical'; self.sort_by='Name'
        self.entries=[]; self.filtered=None; self.index=0; self.offset=0; self.message=''
        self.mode='normal'; self.prompt=''; self.last_key=''; self.yank=[]; self.deleted=False
        self.visual=False; self.search=''; self.running=True; self.write_cd=False
        self.help_view=False; self.log=log
        ensure_dirs(); write_session(self.show_hidden,self.preview,self.split,self.sort_by)
        if log: create_log()
        self.reload()
    def reload(self):
        try:
            arr=[p for p in self.cwd.iterdir() if self.show_hidden or not p.name.startswith('.')]
        except Exception:
            arr=[]
        arr.sort(key=lambda p: entry_sort_key(p,self.sort_by))
        if self.search:
            low=self.search.lower(); arr=[p for p in arr if low in p.name.lower()]
        self.entries=arr
        if self.index>=len(self.entries): self.index=max(0,len(self.entries)-1)
        if self.index<0: self.index=0
    def current(self):
        return self.entries[self.index] if self.entries else None
    def terminal_size(self):
        try: return shutil.get_terminal_size()
        except Exception: return os.terminal_size((80,24))
    def git_branch(self):
        p=self.cwd
        for d in [p]+list(p.parents):
            head=d/'.git'/'HEAD'
            if head.exists():
                try:
                    txt=head.read_text().strip()
                    if txt.startswith('ref:'):
                        return txt.rsplit('/',1)[-1]
                    return txt[:7]
                except Exception: return None
        return None
    def render(self):
        cols, rows = self.terminal_size().columns, self.terminal_size().lines
        if cols < 20 or rows < 5:
            return
        out=[]; out.append('\033[?25l\033[H\033[2J')
        branch=self.git_branch()
        header=f"{FG_CYAN} {self.cwd}{RESET}"
        if branch: header += f" on {BOLD}{FG_MAG}{branch}{RESET}"
        out.append(header[:cols] + '\n')
        if self.message:
            out.append(' ' + self.message[:cols-1] + '\n')
        else:
            out.append('\n')
        if self.help_view:
            maxlines=rows-4
            for line in HELP_TEXT.splitlines()[:maxlines]: out.append(line[:cols]+'\n')
            self._status(out, cols, rows, ' help')
            sys.stdout.write(''.join(out)); sys.stdout.flush(); return
        list_top = 2
        list_height = rows - 3
        if self.preview and self.split=='Horizontal': list_height=max(3, rows//2-2)
        if self.index < self.offset: self.offset=self.index
        if self.index >= self.offset+list_height: self.offset=self.index-list_height+1
        visible=self.entries[self.offset:self.offset+list_height]
        name_width=max(10, cols-24)
        if self.preview and self.split=='Vertical': name_width=max(10, cols//2-12)
        for i,p in enumerate(visible):
            idx=self.offset+i; cur=(idx==self.index); prefix='> ' if cur else '  '
            try: st=p.lstat(); mtime=fmt_time(st.st_mtime)
            except Exception: mtime=''
            col=color_for(p); nm=safe_name(p)
            if self.search and self.search.lower() in nm.lower(): nm=BOLD+nm+RESET+col
            raw = (prefix + col + nm + RESET)
            plain_len = 2 + len(safe_name(p))
            spaces = max(1, name_width-plain_len)
            line = raw + ' '*spaces + col + (' '+mtime if mtime else '') + RESET
            out.append(line[:cols+80] + '\n')
        # fill remaining list area
        for _ in range(max(0, list_height-len(visible))): out.append('\n')
        if self.preview:
            cur=self.current(); prev_lines=[]
            if cur:
                if cur.is_dir():
                    try: prev_lines=[FG_GRAY+'─ '+x.name+RESET for x in sorted(cur.iterdir(), key=lambda x:x.name.lower())[:max(1,rows//2)]]
                    except Exception: prev_lines=[]
                else:
                    try:
                        data=cur.read_bytes()[:8192]
                        if b'\0' in data or sum(1 for b in data[:1024] if b<9 or (13<b<32))>20:
                            prev_lines=['(binary file)']
                        else:
                            prev_lines=data.decode('utf-8','replace').splitlines()[:max(1,rows//2)] or ['']
                    except Exception: prev_lines=[]
            if self.split=='Horizontal':
                out.append('\n')
                for l in prev_lines[:rows-len(out)-1]: out.append(str(l)[:cols]+'\n')
            # vertical preview approximation is intentionally modest; tmux captures list primarily.
        status=self.status_text()
        if self.mode in ('command','input_file','input_dir','search','rename','z'):
            status=self.prompt
        self._status(out, cols, rows, status)
        sys.stdout.write(''.join(out)); sys.stdout.flush()
    def _status(self,out,cols,rows,text):
        # Move to bottom row and draw reverse-video status/prompt.
        out.append(f"\033[{rows};1H{REV}{text[:cols].ljust(cols)}{RESET}")
    def status_text(self):
        n=len(self.entries); cur=self.current()
        if self.search:
            return f" /{self.search} - {n} matches"
        if not cur: return ' 0/0'
        try: st=cur.lstat(); sz=human_size(st.st_size); perm=mode_octal(st); ext=ext_name(cur)
        except Exception: sz='0B'; perm='---'; ext=''
        mid=(ext+' ') if ext else ''
        return f" {self.index+1}/{n} {mid}{sz} {perm}"
    def move(self,delta):
        if self.entries:
            self.index=max(0,min(len(self.entries)-1,self.index+delta))
    def change_dir(self,path,remember=True):
        p=Path(path).expanduser()
        if not p.is_absolute(): p=(self.cwd/p)
        try: p=p.resolve()
        except Exception: pass
        if p.is_dir():
            if remember: self.history.append(self.cwd)
            self.cwd=p; self.forward.clear(); self.index=0; self.offset=0; self.search=''; self.message=''; self.reload()
        else:
            self.message='Invalid path.'
    def open_current(self):
        p=self.current()
        if not p: return
        if p.is_dir(): self.change_dir(p)
        else: self.message=''
    def parent(self):
        if self.cwd.parent != self.cwd: self.change_dir(self.cwd.parent)
    def make_file(self,name):
        if not name: return
        p=self.cwd/name
        try: p.touch(exist_ok=False); self.message=''; self.reload(); self.select_name(name)
        except FileExistsError: self.message='Already exists.'
        except Exception: self.message='Failed to create file.'
    def make_dir(self,name):
        if not name: return
        p=self.cwd/name
        try: p.mkdir(); self.message=''; self.reload(); self.select_name(name)
        except FileExistsError: self.message='Already exists.'
        except Exception: self.message='Failed to create directory.'
    def select_name(self,name):
        for i,p in enumerate(self.entries):
            if p.name==name: self.index=i; break
    def delete_current(self):
        p=self.current()
        if not p: return
        _,trash,_=ensure_dirs(); trash.mkdir(parents=True, exist_ok=True)
        dest=trash/(str(int(time.time()*1000000)%10000000000)+'_'+p.name)
        try:
            shutil.move(str(p), str(dest)); self.yank=[dest]; self.deleted=True; self.message='1 item deleted. [0.00s]'; self.reload()
        except Exception: self.message='Failed to delete.'
    def yank_current(self):
        p=self.current()
        if p: self.yank=[p]; self.deleted=False; self.message='1 item yanked.'
    def put(self):
        if not self.yank: return
        count=0
        for src in self.yank:
            src=Path(src); name=src.name
            if self.deleted and '_' in name: name=name.split('_',1)[1]
            dst=unique_dest(self.cwd,name)
            try:
                copy_item(src,dst); count+=1
            except Exception: pass
        self.message=f"{count} item inserted. [0.00s]" if count==1 else f"{count} items inserted. [0.00s]"
        self.reload()
    def extract_current(self):
        p=self.current()
        if not p or p.is_dir():
            self.running=False; return
        ok,msg=unpack_archive(p); self.message=msg; self.reload()
        # Select first newly-created numbered item when present.
        pref=p.name+'_'
        for i,e in enumerate(self.entries):
            if e.name.startswith(pref): self.index=i; break
    def command(self,cmd):
        cmd=cmd.strip()
        if cmd in ('q','quit'):
            self.running=False; return
        if cmd=='h': self.help_view=True; return
        if cmd=='e': self.reload(); self.message=''; return
        if cmd.startswith('cd'):
            arg=cmd[2:].strip(); self.change_dir(Path.home() if not arg else arg); return
        if cmd=='config': self.change_dir(config_home()/'felix'); return
        if cmd=='trash':
            _,trash,_=ensure_dirs(); self.change_dir(trash); return
        if cmd=='empty':
            _,trash,_=ensure_dirs()
            try:
                for x in trash.iterdir():
                    if x.is_dir(): shutil.rmtree(x)
                    else: x.unlink()
                self.message='Trash emptied.'; self.reload()
            except Exception: self.message='Failed to empty trash.'
            return
        if cmd=='reg': self.message='register 0: ' + ', '.join(Path(x).name for x in self.yank); return
        if cmd:
            try:
                r=subprocess.run(cmd, cwd=str(self.cwd), shell=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                self.message=f"Command exited with status {r.returncode}." if r.returncode else ''
                self.reload()
            except Exception: self.message='Command failed.'
    def exit_with_cd(self):
        pid=os.environ.get('SHELL_PID')
        if pid:
            rb=runtime_base(); rb.mkdir(parents=True, exist_ok=True)
            try: (rb/pid).write_text(str(self.cwd))
            except Exception: pass
        self.running=False
    def handle(self,ch):
        if self.mode!='normal':
            if ch in ('\x1b',): self.mode='normal'; self.prompt=''; return
            if ch in ('\r','\n'):
                text=self.prompt[1:] if self.prompt else ''
                m=self.mode; self.mode='normal'; self.prompt=''
                if m=='command': self.command(text)
                elif m=='input_file': self.make_file(text)
                elif m=='input_dir': self.make_dir(text)
                elif m=='search': self.search=text; self.index=0; self.offset=0; self.reload()
                elif m=='rename': self.rename_current(text)
                elif m=='z': self.change_dir(Path.home() if not text.strip() else text.strip())
                return
            if ch in ('\x7f','\b','\x08'):
                self.prompt=self.prompt[:-1] if len(self.prompt)>1 else self.prompt; return
            if ch=='\x12': return
            if len(ch)==1 and ord(ch)>=32:
                self.prompt += ch
            return
        if self.help_view:
            if ch in ('q','\x1b','h',':'): self.help_view=False
            if ch==':': self.mode='command'; self.prompt=':'
            return
        # escape sequences
        if ch.startswith('\x1b['):
            if ch.endswith('A'): self.move(-1)
            elif ch.endswith('B'): self.move(1)
            elif ch.endswith('C'): self.open_current()
            elif ch.endswith('D'): self.parent()
            return
        if ch in ('j',): self.move(1)
        elif ch in ('k',): self.move(-1)
        elif ch=='\x04': self.move(max(1,self.terminal_size().lines//2))
        elif ch=='\x15': self.move(-max(1,self.terminal_size().lines//2))
        elif ch in ('\r','\n','l'): self.open_current()
        elif ch=='h': self.parent()
        elif ch=='G': self.index=max(0,len(self.entries)-1)
        elif ch=='g':
            if self.last_key=='g': self.index=0; self.last_key=''; return
        elif ch=='i': self.mode='input_file'; self.prompt='i'
        elif ch=='I': self.mode='input_dir'; self.prompt='I'
        elif ch==':': self.mode='command'; self.prompt=':'
        elif ch=='/': self.mode='search'; self.prompt='/'
        elif ch=='z': self.mode='z'; self.prompt='z'
        elif ch=='n': self.move(1)
        elif ch=='N': self.move(-1)
        elif ch=='v': self.preview=not self.preview; write_session(self.show_hidden,self.preview,self.split,self.sort_by)
        elif ch=='s': self.split='Horizontal' if self.split=='Vertical' else 'Vertical'; write_session(self.show_hidden,self.preview,self.split,self.sort_by)
        elif ch in ('\x7f','\b','\x08'):
            self.show_hidden=not self.show_hidden; self.index=0; self.reload(); write_session(self.show_hidden,self.preview,self.split,self.sort_by)
        elif ch=='t':
            self.sort_by='Modified' if self.sort_by=='Name' else 'Name'; self.index=0; self.reload(); write_session(self.show_hidden,self.preview,self.split,self.sort_by)
        elif ch=='y':
            if self.last_key=='y': self.yank_current(); self.last_key=''; return
        elif ch=='d':
            if self.last_key=='d': self.delete_current(); self.last_key=''; return
        elif ch=='p': self.put()
        elif ch=='e': self.extract_current()
        elif ch=='u': self.message='Already at oldest change.'
        elif ch=='\x12': self.message='Already at newest change.'
        elif ch=='c': self.mode='rename'; self.prompt='c'
        elif ch=='Z':
            if self.last_key=='Z': self.running=False; self.last_key=''; return
        elif ch=='Q':
            if self.last_key=='Z': self.exit_with_cd(); self.last_key=''; return
        self.last_key=ch
    def rename_current(self,newname):
        p=self.current()
        if not p or not newname: return
        try:
            p.rename(self.cwd/newname); self.message='1 item renamed. [0.00s]'; self.reload(); self.select_name(newname)
        except Exception: self.message='Failed to rename.'
    def read_key(self):
        ch=sys.stdin.read(1)
        if ch=='\x1b':
            # gather a short escape sequence if present
            seq=ch
            while select.select([sys.stdin],[],[],0.01)[0]:
                seq += sys.stdin.read(1)
                if len(seq)>8: break
            return seq
        return ch
    def run(self):
        if not sys.stdin.isatty() or not sys.stdout.isatty():
            sys.stderr.write('Error: Cannot detect terminal size\n'); return
        try:
            sz=shutil.get_terminal_size()
        except Exception:
            sys.stderr.write('Error: Cannot detect terminal size\n'); return
        if sz.columns < 20 or sz.lines < 5:
            sys.stderr.write('Error: Too small window size\n'); return
        old=termios.tcgetattr(sys.stdin.fileno())
        try:
            tty.setcbreak(sys.stdin.fileno())
            sys.stdout.write('\033[?1049h\033[?25l'); sys.stdout.flush()
            while self.running:
                self.render()
                r,_,_=select.select([sys.stdin],[],[],0.5)
                if r:
                    ch=self.read_key()
                    if ch=='': break
                    self.handle(ch)
            write_session(self.show_hidden,self.preview,self.split,self.sort_by)
        finally:
            try: termios.tcsetattr(sys.stdin.fileno(), termios.TCSADRAIN, old)
            except Exception: pass
            sys.stdout.write('\033[0m\033[?25h\033[?1049l'); sys.stdout.flush()

def parse_and_run(argv):
    # Observed simple parser: one non-log argument may be a path; any other two-argument
    # form (unless leading --log/-l) prints help.
    if len(argv)==1:
        path='.'; log=False
    elif len(argv)==2:
        a=argv[1]
        if a in ('--help','-h'):
            sys.stdout.write(HELP_TEXT); return 0
        if a=='--init':
            sys.stdout.write(INIT_TEXT); return 0
        if a in ('--log','-l'):
            path='.'; log=True
        else:
            path=a; log=False
    elif len(argv)==3 and argv[1] in ('--log','-l'):
        sys.stdout.write('\n')
        path=argv[2]; log=True
    else:
        sys.stdout.write(HELP_TEXT); return 0
    p=Path(path).expanduser()
    if not p.exists(): invalid_path(path); return 0
    if not p.is_dir(): sys.stderr.write('Path should be directory.\n`fx -h` shows help.\n'); return 0
    App(p, log=log).run()
    return 0

if __name__=='__main__':
    try: sys.exit(parse_and_run(sys.argv))
    except KeyboardInterrupt: sys.exit(0)
