    def handle(self,ch):
        if self.mode!='normal':
            if ch in ('\x1b',): self.mode='normal'; self.prompt=''; return
            if ch in ('\r','\n'):
                text=self.prompt[1:] if self.prompt else ''
                m=self.mode; self.mode='normal'; self.prompt=''
                if m=='command': self.command(text)
                elif m=='input_file': self.make_file(text)
                elif m=='input_dir': self.make_dir(text)
                elif m=='search': self.search=text; self.index=0; self.offset=0; self.reload()
                elif m=='rename': self.rename_current(text)
                elif m=='z': self.change_dir(Path.home() if not text.strip() else text.strip())
                return
            if ch in ('\x7f','\b','\x08'):
                self.prompt=self.prompt[:-1] if len(self.prompt)>1 else self.prompt; return
            if ch=='\x12': return
            if len(ch)==1 and ord(ch)>=32:
                self.prompt += ch
            return
        if self.help_view:
            if ch in ('q','\x1b','h',':'): self.help_view=False
            if ch==':': self.mode='command'; self.prompt=':'
            return
